#!/bin/sh
# Print the three most frequent client addresses.  Since candidates are
# considered in log order, equal counts retain their first-seen ordering.
exec awk '
{
    ip = $1
    if (!(ip in first_seen)) {
        first_seen[ip] = ++address_count
        address[address_count] = ip
    }
    hits[ip]++
}
END {
    printed = 0
    while (printed < 3) {
        best = ""
        for (i = 1; i <= address_count; i++) {
            ip = address[i]
            if (!(ip in selected) &&
                (best == "" || hits[ip] > hits[best])) {
                best = ip
            }
        }

        if (best == "")
            exit
        print best
        selected[best] = 1
        printed++
    }
}
' access.log
